            background-color: #2a2a2a;
            border-left: 4px solid #4ade80;
            padding: 30px;
            margin-bottom: 30px;
            border-radius: 4px;
            border: 1px solid #555555;
        }

        .info-message p {
            font-size: 18px;
            line-height: 1.6;
            margin-bottom: 15px;
            color: #ffffff;
        }

        .info-message p:last-child {
            margin-bottom: 0;
        }

        .confirm-button {
            display: inline-block;
            background: linear-gradient(135deg, #4ade80 0%, #22c55e 100%);
            color: #000000;
            text-decoration: none;
            padding: 20px 50px;
            border-radius: 30px;
            font-size: 20px;
            font-weight: bold;
            box-shadow: 0 4px 20px rgba(74, 222, 128, 0.3);
            border: 2px solid #4ade80;
            transition: all 0.3s ease;
            cursor: pointer;
            margin: 20px 0;
        }

        .confirm-button:hover {
            background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%);
            box-shadow: 0 6px 25px rgba(74, 222, 128, 0.4);
            transform: translateY(-2px);
        }

        .footer {
            background-color: #2a2a2a;
            padding: 20px;
            border-top: 1px solid #555555;
        }

        .footer p {
            font-size: 14px;
            color: #ffffff;
            font-weight: bold;
            margin-bottom: 10px;
        }

        .footer .services {
            font-size: 12px;
            color: #cccccc;
            margin-bottom: 5px;
        }

        .footer .website {
            font-size: 12px;
            color: #cccccc;
            margin-bottom: 15px;
        }

        .footer .website a {
            color: #888888;
            text-decoration: none;
            font-weight: bold;
        }

        .footer .divider {
            border-top: 1px solid #555555;
            padding-top: 15px;
            margin-top: 15px;
        }

        .footer .powered {
            font-size: 11px;
            color: #999999;
            margin-bottom: 5px;
        }      

        .click-icon {
            font-size: 64px;
            margin-bottom: 20px;
            animation: pulse 2s infinite;
        }

        @keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.1); }
        }

