            .container {
                margin: 10px;
            }

            .header h1 {
                font-size: 28px;
            }

            .info-message p {
                font-size: 16px;
            }

            .content {
                padding: 30px 15px;
            }

            .confirm-button {
                font-size: 18px;
                padding: 15px 40px;
            }
